// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        amount = bound(amount, 0, 1000 ether);
        vm.assume(receiver != address(0) && receiver != address(c));

        vm.deal(address(c), 2000 ether);

        uint256 balanceBefore = address(c).balance;
        bool ok;

        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;

        assertTrue(!ok || balanceAfter < balanceBefore);
    }
}
